// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the owner address that will be set via initialize (initializer uses msg.sender)
    // We fuzz an address that will be the deployer/prank sender when calling initialize
    function testFuzz_property(address potentialOwner) public {
        // keep domain wide but non-zero to avoid zero-address initialization issues if any
        // still allow zero to be tested as well; no tight restrictions

        // Call initialize as if potentialOwner is msg.sender
        vm.prank(potentialOwner);
        // initialize requires (uint256 credChainId_, uint256 credId_, string memory verificationType_, address protocolFeeDestination_)
        // We fuzz only the msg.sender; provide fixed other args
        c.initialize(1, 2, "v", address(0xdead));

        // Query the stored owner via the public owner() getter
        address reportedOwner = c.owner();

        // The general rule: reportedOwner must equal the stored owner (which was set to the initializer msg.sender)
        // We assert that owner() == potentialOwner
        // This holds for the reference implementation for all inputs; the mutant that adds +1 to returned owner will fail for any potentialOwner where
        // address(uint160(potentialOwner)) + 1 != uint160(potentialOwner) (i.e., almost all addresses), so fuzzer can find a counterexample
        assertTrue(reportedOwner == potentialOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the initializer caller address; the correct contract should always return the exact owner
    // after initialize is called by that caller. The mutant that adds +1 to the stored owner will
    // cause the returned owner() to differ for some callers (and the fuzzer will find one).
    function testFuzz_property(address initializer) public {
        // avoid zero address because Ownable.__Ownable_init reverts on address(0)
        vm.assume(initializer != address(0));

        // make the fuzzer-supplied address be the msg.sender for initialize
        vm.prank(initializer);
        // call initialize with some wide parameters; values don't matter much for owner logic
        c.initialize(1, 2, "v", address(0x1234));

        // exactly one assertion: the stored owner (as returned by c.owner()) equals the initializer
        // correct contract: owner() == initializer for every admissible initializer (non-zero)
        // mutant: for some initializer this will fail because mutant returns initializer + 1
        address reportedOwner = c.owner();
        assertTrue(reportedOwner == initializer);
    }
}

