// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: paused() must reflect the internal paused flag; specifically,
    // after calling pause() the public paused() must return true, and after calling unPause() it must return false.
    // We fuzz a boolean 'startPaused' to decide which transition to perform; the correct contract always satisfies
    // paused() == startPaused after performing the corresponding action, while the mutant that flips the return
    // will fail for at least one branch.
    function testFuzz_property(bool startPaused) public {
        // keep domain wide; no assumptions needed

        // Ensure caller is owner (deployer), which is msg.sender in initialize in real flows.
        // The contract was constructed with _disableInitializers in constructor; to simulate typical usage we
        // directly use pause/unPause which are callable by owner (the test contract is the deployer/owner of c).

        if (startPaused) {
            // call pause() and expect paused() to be true
            c.pause();
            bool ok;
            try c.paused() returns (bool val) {
                ok = val == true;
            } catch {
                // If call reverts, treat as violation (should not revert)
                ok = false;
            }
            assertTrue(ok);
        } else {
            // ensure it's unpaused: call unPause() then expect paused() false
            // If paused initially, unPause will succeed only if owner; safe to call unPause() regardless
            // because calling unPause() when not paused should revert ExpectedPause(). To keep wide, we attempt both:
            // First try to unpause; if it reverts because not paused, that's fine — paused() should already be false.
            bool didUnpause = true;
            try c.unPause() {
            } catch {
                didUnpause = false;
            }

            bool ok;
            try c.paused() returns (bool val) {
                ok = (val == false);
            } catch {
                ok = false;
            }
            assertTrue(ok);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed param: whether to call pause (true) or unPause (false) as the deciding input
    function testFuzz_property(bool doPause) public {
        // admissible domain: none to restrict; both branches are valid

        // Ensure caller is owner (deployer in setUp)
        address owner = address(this);
        // contract was initialized via constructor disable; need to initialize as owner
        // initialize expects (credChainId_, credId_, verificationType_, protocolFeeDestination_)
        c.initialize(1, 2, "v", address(0));

        // Drive contract to paused/unpaused according to fuzz input
        if (doPause) {
            c.pause();
        } else {
            // ensure it's paused first so unPause has effect when doPause == false sometimes
            // but calling unPause on an unpaused contract will revert; only call when paused
            // So we only call unPause if currently paused: pause then unpause when doPause==false
            // To keep admissible domain wide and avoid revert, perform safe sequence:
            c.pause();
            c.unPause();
        }

        // Now read paused() via public view
        bool reportedPaused = c.paused();

        // Also derive expected paused state by attempting to call _pause/_unpause effects.
        // Since we controlled the sequence above, the expected internal state is:
        // - if doPause == true: paused
        // - if doPause == false: not paused
        bool expectedPaused = doPause;

        // The general rule: reportedPaused must equal expectedPaused for the correct contract.
        // The mutant flips the boolean and will cause this assertion to fail for some input (doPause==true or false).
        assertTrue(reportedPaused == expectedPaused);
    }
}
